def _projection_bound(g, path):
    """Exact minimum derivative projection on each original chord.

    Its positive minimum is a conservative lower bound on physical speed per
    unit of chord parameter. This avoids treating chord parameter as arc length.
    A nonpositive projection cannot certify the finite taper and rejects it.
    """
    i = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    n = c._count(g, path)
    point = c._vec(g, c.named(g, 'st_cc_p', 'FLOAT_VECTOR'))
    following = c._vec(g, c._read(g, path, 'st_cc_p', g.math('MINIMUM', i+1., n-1.), 'FLOAT_VECTOR'))
    direction = c._unit(g, c._sub(following, point))
    span = g.math('MAXIMUM', c.named(g, 'st_cc_span'), 1e-12)
    a, b, d = [c._dot(c._vec(g, c.named(g, 'st_cc_'+key, 'FLOAT_VECTOR')), direction)/span
               for key in ('a', 'b', 'c')]
    quadratic, linear = 3.*d, 2.*b
    vertex = c.bounded(g, -linear/c.choose(g, g.math('GREATER_THAN', g.math('ABSOLUTE', quadratic), 1e-12), 2.*quadratic, 1.))
    low = g.math('MINIMUM', a, a+linear+quadratic)
    low = g.math('MINIMUM', low, a+linear*vertex+quadratic*vertex*vertex)
    return c._stat(g, path, c.choose(g, g.math('LESS_THAN', i, n-1.5), low, 1e8))


