def evaluate(*, second_derivatives=False, placed=False):
    """Constant Section dimensions plus finite quintic corrections at seams."""
    name = PREFIX+('quintic dimension second derivatives v1' if second_derivatives else 'quintic dimension field v1')
    if placed:
        name += ' / Bounded placement v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    for key in ('Path', 'Transitions'):
        g.socket(key, 'NodeSocketGeometry')
    g.socket('Parameter', 'NodeSocketFloat')
    for key in ('Width', 'Offset', 'Width Derivative', 'Offset Derivative'):
        g.socket(key, 'NodeSocketFloat', 'OUTPUT')
    if second_derivatives:
        for key in ('Width Second Derivative','Offset Second Derivative'):
            g.socket(key,'NodeSocketFloat','OUTPUT')
    for key in ('Section ID', 'Transition ID'):
        g.socket(key, 'NodeSocketInt', 'OUTPUT')
    inp = g.node('NodeGroupInput'); path = inp.outputs['Path']; transitions = inp.outputs['Transitions']
    s = c.V(g, inp.outputs['Parameter'])
    def predecessor(geometry, key):
        nearest = g.node('GeometryNodeSampleNearest'); nearest.domain = 'POINT'
        g.bind(geometry, nearest.inputs['Geometry']); g.bind(g.xyz(s), nearest.inputs['Sample Position'])
        index = c.V(g, nearest.outputs['Index'])
        return index-g.math('GREATER_THAN', c._read(g, geometry, key, index), s)
    at = c.bounded(g, predecessor(path, 'st_cc_knot'), 0., c._count(g, path)-2.)
    width = c._read(g, path, 'st_cd_width', at); offset = c._read(g, path, 'st_cd_offset', at)
    section = c._read(g, path, 'st_cd_section', at, 'INT')
    before = predecessor(transitions, 'st_cd_station'); count = c._count(g, transitions)
    dw, do, ddw, ddo, identity = 0., 0., 0., 0., -1
    for index in (before, before+1.):
        def read(key, kind='FLOAT'):
            return c._read(g, transitions, 'st_cd_'+key, index, kind)
        half = read('half'); distance = s-read('station')
        t = c.bounded(g, g.math('ABSOLUTE', distance)/g.math('MAXIMUM', half, 1e-12))
        enabled = g.math('GREATER_THAN', index, -.5)*g.math('LESS_THAN', index, count-.5)*g.math('GREATER_THAN', half, 1e-8)
        weight = enabled*(1.-t*t*t*(10.+t*(-15.+6.*t)))
        rate = -enabled*g.math('SIGN', distance)*30.*t*t*(1.-t)*(1.-t)/g.math('MAXIMUM', half, 1e-12)
        if second_derivatives:
            acceleration = -enabled*60.*t*(1.-t)*(1.-2.*t)/(g.math('MAXIMUM',half,1e-12)**2.)
        first = g.math('LESS_THAN', distance, 0.)
        changes = []
        for key in ('width', 'offset'):
            a, b = read('before_'+key), read('after_'+key)
            changes.append(.5*(a+b)-c.choose(g, first, a, b))
        shifted = read('placed', 'BOOLEAN')*enabled if placed else 0.
        if placed:
            weight = weight*(1.-shifted); rate = rate*(1.-shifted)
            if second_derivatives:
                acceleration = acceleration*(1.-shifted)
        width = width+weight*changes[0]; offset = offset+weight*changes[1]
        dw = dw+rate*changes[0]; do = do+rate*changes[1]
        if second_derivatives:
            ddw = ddw+acceleration*changes[0]; ddo = ddo+acceleration*changes[1]
        legacy_enabled = enabled*(1.-shifted) if placed else enabled
        identity = c.choose(g, legacy_enabled*g.math('LESS_THAN', t, 1.), read('id', 'INT'), identity, 'INT')
        if placed:
            begin, end = read('interval_start'), read('interval_end')
            duration = g.math('MAXIMUM', end-begin, 1e-12)
            q = c.bounded(g, (s-begin)/duration)
            inside = shifted*g.math('GREATER_THAN', s, begin-1e-7)*g.math('LESS_THAN', s, end+1e-7)
            blend = q*q*q*(10.+q*(-15.+6.*q))
            derivative = 30.*q*q*(1.-q)*(1.-q)/duration
            second = 60.*q*(1.-q)*(1.-2.*q)/(duration*duration) if second_derivatives else 0.
            for key, value, rate_value, second_value in (('width', width, dw, ddw), ('offset', offset, do, ddo)):
                a, b = read('before_'+key), read('after_'+key)
                value = c.choose(g, inside, a+(b-a)*blend, value)
                rate_value = c.choose(g, inside, (b-a)*derivative, rate_value)
                if second_derivatives:
                    second_value = c.choose(g, inside, (b-a)*second, second_value)
                if key == 'width':
                    width, dw, ddw = value, rate_value, second_value
                else:
                    offset, do, ddo = value, rate_value, second_value
            identity = c.choose(g, inside, read('id', 'INT'), identity, 'INT')
    out = g.node('NodeGroupOutput')
    for key, value in (('Width', width), ('Offset', offset), ('Width Derivative', dw),
                       ('Offset Derivative', do), ('Section ID', section), ('Transition ID', identity)):
        g.bind(value, out.inputs[key])
    if second_derivatives:
        g.bind(ddw,out.inputs['Width Second Derivative']);g.bind(ddo,out.inputs['Offset Second Derivative'])
    return g.g
